sysevent_script_action.script:
var getCaseSuppressionLogicLiveCheck = gs.getProperty('x_hsb11_hsbc_mss_o.anamoly_suppressionlogic_isactive'); // Checking if case suppression logic value.
if (getCaseSuppressionLogicLiveCheck == "false")
    anomalycaseCreation(current.objectid.toString(), current.eventstatus.toString(), current.eventdatetime.toString(), current.objectversion.toString());

function anomalycaseCreation(objectid, eventstatus, eventdatetime, objectversion) {


    var anmolyCase = new GlideRecord('x_hsb11_hsbc_mss_o_anomaly');
	var datetime = new GlideDateTime((current.eventdatetime).getDisplayValue());
    var shortDesc = gs.getProperty("hsbc.anomaly.case.short.description");
    anmolyCase.addQuery('short_description', shortDesc + ' : ' + current.eventstatus);
    anmolyCase.query();
    if (!anmolyCase.next()) {
        anmolyCase.initialize();


        anmolyCase.setValue("short_description", (shortDesc + ' : ' + current.eventstatus));

        anmolyCase.description = 'Object Id is ' + current.objectid + ' Object Version is ' + current.objectversion + ' Eventstatus is ' + current.eventstatus + ' Eventdatetime is ' + datetime + '\nTask Overview: A event from CTAC has been received that ServiceNow does not recognize.' + '\nStep 1:  Review this event through the Trade details provided or within CTAC and select one of the following outcomes:' + '\nIf the event is relevant to the trade and should be added to the ServiceNow configuration, select in the Outcome field ' + 'Issue Resolved' + '. This will be reviewed by the Continuous Improvement team to determine what updates need to be made to the process flows and create the corresponding change request.' + '\nIf the event is an anomaly and is not relevant to the trade, select in the Outcome field ' + 'Rejected. ' + '\nThis should update the Task Status field to Closed Complete.';

        var assignGroup = gs.getProperty("hsbc.anomaly.case.assignmentgroup"); // Group: HBAP CE Clearing and Settlement -  MOCS

        anmolyCase.setValue("assignment_group", assignGroup);
        anmolyCase.insert();
    }
}
